VALUES ('li-xiong', '李雄', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '巴氐李特之子，304年据成都起兵，306年称成都王，建立成汉并据有益州；在位时招纳流民、恢复蜀地秩序，政权由此延续至347年。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李雄_(十六国)"}]'::jsonb, '武皇帝', '太宗', '成汉武皇帝')
