VALUES ('shi-hu', '石虎', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '石勒养子，334年废石弘自立，后称帝并迁都邺城；大举营建与频繁征伐加重国力消耗，其死后诸子争位，后赵迅速分裂。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石虎"},{"label":"《资治通鉴》卷95","url":"https://zh.wikisource.org/wiki/資治通鑑/卷095"},{"label":"資治通鑑/卷098","url":"https://zh.wikisource.org/wiki/資治通鑑/卷098"}]'::jsonb, '武皇帝', '太祖', '后赵武皇帝')
