VALUES ('shi-shi', '石世', ARRAY[]::text[], NULL, NULL, 339, 1, NULL, 'year', 349, 6, NULL, 'month', ARRAY['皇帝'], '石虎幼子，349年石虎死后由太后拥立；在位三十三日即被石遵废杀，后赵进入连续政变。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石世"},{"label":"資治通鑑/卷098","url":"https://zh.wikisource.org/wiki/資治通鑑/卷098"}]'::jsonb, NULL, NULL, '后赵少帝')
