VALUES ('shi-zun', '石遵', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '石虎之子，349年废杀石世自立；因未能安抚诸军，同年被冉闵发动兵变杀死。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石遵"}]'::jsonb, NULL, NULL, '后赵皇帝')
