VALUES ('shi-jian', '石鉴', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '石虎之子，石遵死后于349年被冉闵拥立；次年冉闵杀石鉴并控制邺城，石氏政权失去中枢。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石鉴"}]'::jsonb, NULL, NULL, '后赵皇帝')
