VALUES ('shi-zhi', '石祗', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '石虎之子，冉闵杀石鉴后在襄国称帝，延续石氏后赵；351年被部将刘显攻杀，后赵正式灭亡。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/石祗"}]'::jsonb, NULL, NULL, '后赵末帝')
