VALUES ('zhang-gui', '张轨', ARRAY['士彦'], NULL, NULL, 255, 1, NULL, 'year', 314, 6, 20, 'day', ARRAY['君主'], '安定张氏出身，字士彦。西晋凉州刺史，前凉奠基者；永嘉之乱后保境安民，河西安定。卒谥武公。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张轨"},{"label":"太平御覽/0124","url":"https://zh.wikisource.org/wiki/太平御覽/0124"},{"label":"晉書/卷086","url":"https://zh.wikisource.org/wiki/晉書/卷086"}]'::jsonb, '武公', NULL, '前凉武公')
