VALUES ('zhang-shi', '张寔', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '张轨之子，张轨死后于314年继掌凉州；承袭父亲保境安民、奉晋正朔的政策，抵御地方叛乱，奠定张氏河西政权。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张寔"},{"label":"太平御覽/0124","url":"https://zh.wikisource.org/wiki/太平御覽/0124"},{"label":"晉書/卷086","url":"https://zh.wikisource.org/wiki/晉書/卷086"}]'::jsonb, '昭王', NULL, '前凉昭王')
