VALUES ('zhang-jun', '张骏', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '张寔之子，324年继位；前凉在其统治下势力扩展至西域和河西诸郡，名义上奉晋，成为张氏政权的强盛时期。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张骏_(十六国)"}]'::jsonb, '文王', NULL, '前凉文王')
