VALUES ('zhang-chonghua', '张重华', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '张骏之子，346年继位；年少时由大臣辅政，持续抵御后赵及前秦压力，353年去世后由幼子张耀灵承位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张重华"}]'::jsonb, '桓王', NULL, '前凉桓王')
