VALUES ('zhang-zuo', '张祚', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '张骏之子，353年废杀侄子张耀灵夺位并称帝；统治失政，355年为张天锡等所杀，前凉恢复张氏宗室继承。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张祚_(前凉)"}]'::jsonb, '威王', NULL, '前凉威王')
