VALUES ('zhang-xuanjing', '张玄靓', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '张重华之子，幼年继位，长期由张天锡等权臣辅政；363年张天锡发动政变，废张玄靓为凉王并将其杀害。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张玄靓"}]'::jsonb, '冲王', NULL, '前凉冲王')
