VALUES ('zhang-tianxi', '张天锡', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '张骏之子，363年夺位；前凉在前秦扩张下日益孤立，376年苻坚大军来攻时出降，张氏政权终结。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张天锡_(前凉)"},{"label":"資治通鑑/卷101","url":"https://zh.wikisource.org/wiki/資治通鑑/卷101"}]'::jsonb, NULL, NULL, '前凉末王')
