VALUES ('murong-jun', '慕容儁', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '慕容皝之子，348年继位，352年称帝；迁都邺城并灭冉魏，前燕疆域扩至华北，360年死后由子慕容暐继位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容儁"},{"label":"資治通鑑/卷101","url":"https://zh.wikisource.org/wiki/資治通鑑/卷101"}]'::jsonb, '景昭皇帝', NULL, '前燕景昭皇帝')
