VALUES ('murong-wei', '慕容暐', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '慕容儁之子，幼年即位，政务由慕容恪等辅佐；慕容恪死后朝政失衡，370年苻坚攻陷邺城，前燕亡，慕容暐降秦。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容暐"},{"label":"資治通鑑/卷101","url":"https://zh.wikisource.org/wiki/資治通鑑/卷101"}]'::jsonb, NULL, NULL, '前燕末帝')
