VALUES ('fu-jian', '苻健', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '氐族苻洪之子，350年入关中称秦王，351年称天王，建立前秦；平定关中后整顿政务，355年去世，由子苻生继位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/苻健"}]'::jsonb, '景明皇帝', '高祖', '前秦景明皇帝')
