VALUES ('fu-sheng', '苻生', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '苻健之子，355年继位；统治以严酷猜忌著称，357年被堂弟苻坚废杀，前秦政权转向整合扩张。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/苻生"}]'::jsonb, NULL, NULL, '前秦废帝')
