VALUES ('fu-jian-ming', '苻坚', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '苻健族孙，357年推翻苻生即位；任用王猛改革并先后灭前燕、前凉及代国，统一北方，383年南征败于淝水，帝国随即瓦解，苻坚于385年被姚苌杀害。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/苻坚"}]'::jsonb, '宣昭皇帝', '世祖', '前秦宣昭皇帝')
