VALUES ('fu-pi', '苻丕', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '苻坚长子，淝水败后于385年在晋阳称帝，收集前秦余部；东晋北伐与后秦进攻令其势力受挫，386年战败被东晋将领冯该杀死。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/苻丕"}]'::jsonb, '哀平皇帝', NULL, '前秦哀平皇帝')
