VALUES ('fu-deng', '苻登', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '苻坚族孙，386年在枹罕即位，凭借羌氐部众与后秦长期争战；394年兵败被姚兴俘杀，前秦仅余苻崇一支。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/苻登"}]'::jsonb, '高皇帝', '太宗', '前秦高皇帝')
