VALUES ('fu-chong', '苻崇', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '苻登之子，394年继位后退保湟中；同年为西秦乞伏乾归击败并杀死，前秦亡。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/苻崇"}]'::jsonb, NULL, NULL, '前秦末帝')
