VALUES ('murong-bao', '慕容宝', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '慕容垂第四子，396年继位；次年参合陂之败削弱后燕，慕容宝退守中山，398年为兰汗所杀，后燕陷入分裂。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容宝"}]'::jsonb, '惠愍皇帝', '烈宗', '后燕惠愍皇帝')
