VALUES ('murong-sheng', '慕容盛', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '慕容宝庶长子，398年兰汗篡位时暂避龙城，随后起兵诛兰汗复国；在位期间平定内乱，401年为部将所杀。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容盛"}]'::jsonb, '昭武皇帝', '中宗', '后燕昭武皇帝')
