VALUES ('murong-de-yan', '慕容德', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '慕容皝少子、慕容垂之弟，后燕分裂后于398年据广固称燕王，建立南燕；定都广固并招抚流民，405年称帝，次年去世。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容德"},{"label":"資治通鑑/卷114","url":"https://zh.wikisource.org/wiki/資治通鑑/卷114"},{"label":"晉書/卷127","url":"https://zh.wikisource.org/wiki/晉書/卷127"}]'::jsonb, '献武皇帝', NULL, '南燕献武皇帝')
