VALUES ('murong-chao', '慕容超', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '慕容德侄，405年继位；南燕与东晋冲突不断，刘裕于409年北伐围攻广固，410年城陷，慕容超被俘送建康处死。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容超"},{"label":"資治通鑑/卷114","url":"https://zh.wikisource.org/wiki/資治通鑑/卷114"},{"label":"晉書/卷127","url":"https://zh.wikisource.org/wiki/晉書/卷127"}]'::jsonb, NULL, NULL, '南燕末帝')
