VALUES ('murong-yi', '慕容义', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '慕容宝之子，407年短暂继位于后燕；同年冯跋发动政变将其废杀，后燕政权由冯氏接掌。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容义"}]'::jsonb, NULL, NULL, NULL)
