VALUES ('murong-xi', '慕容熙', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '慕容垂幼子，401年继位；后燕内政失序，407年冯跋起兵，慕容熙被俘杀，后燕结束。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/慕容熙"}]'::jsonb, NULL, NULL, '后燕末帝')
