VALUES ('feng-ba', '冯跋', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '汉人，曾仕后燕，407年拥立高云并掌权；409年高云被杀后即位，建都和龙，维持北燕与北魏、东晋的周旋，430年去世。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/冯跋"}]'::jsonb, '文成皇帝', NULL, '北燕文成皇帝')
