VALUES ('feng-hong', '冯弘', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '冯跋之弟，430年继位；北魏持续攻取北燕城地，436年和龙陷落后率众逃往高句丽，后被高句丽王所杀。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/冯弘"},{"label":"資治通鑑/卷122","url":"https://zh.wikisource.org/wiki/資治通鑑/卷122"}]'::jsonb, '昭成帝', NULL, '北燕昭成帝')
