VALUES ('yao-xing', '姚兴', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '姚苌之子，394年继位；扩张后秦至关中、陇右及河西东部，提倡佛教并支持鸠摩罗什译经，晚年诸子争权，416年去世后后秦迅速衰弱。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/姚兴"}]'::jsonb, '文桓皇帝', NULL, '后秦文桓皇帝')
