VALUES ('yao-hong', '姚泓', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '姚兴之子，416年继位；内部宗室冲突削弱国力，刘裕北伐于417年攻陷长安，姚泓出降后被杀，后秦亡。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/姚泓"}]'::jsonb, NULL, NULL, '后秦末帝')
