VALUES ('qifu-guoren', '乞伏国仁', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '鲜卑乞伏部首领，前秦淝水败后于385年称大单于、建元建国，建立西秦并据苑川；死后由弟乞伏乾归继位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/乞伏国仁"}]'::jsonb, '武元王', NULL, '西秦武元王')
