VALUES ('qifu-gan', '乞伏乾归', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '乞伏国仁之弟，388年继位并称河南王，后称秦王；一度降附后秦、出奔南凉，409年复国，412年被部下杀害。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/乞伏乾归"}]'::jsonb, '文威皇帝', NULL, '西秦文威皇帝')
