VALUES ('qifu-chipan', '乞伏炽磐', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '乞伏乾归长子，412年继位；西秦势力复振，414年灭南凉并据有河湟，428年去世后由子乞伏暮末继位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/乞伏炽磐"}]'::jsonb, '文昭王', '太祖', '西秦文昭王')
