VALUES ('qifu-mumo', '乞伏暮末', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '乞伏炽磐之子，428年继位；遭夏军进逼后于431年降夏，西秦灭亡，随后被赫连定杀害。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/乞伏暮末"},{"label":"資治通鑑/卷121","url":"https://zh.wikisource.org/wiki/資治通鑑/卷121"}]'::jsonb, NULL, NULL, '西秦末主')
