VALUES ('lu-long', '吕隆', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '吕光之侄，401年由吕超拥立；后凉已被北凉、南凉夹击，403年向后秦姚兴出降，后凉亡。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/吕隆"},{"label":"資治通鑑/卷112","url":"https://zh.wikisource.org/wiki/資治通鑑/卷112"}]'::jsonb, NULL, NULL, '后凉末主')
