VALUES ('tufa-lilugu', '秃发利鹿孤', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '秃发乌孤之弟，399年继位；以广武为都并与后凉、北凉及西秦周旋，402年让位于弟秃发傉檀。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秃发利鹿孤"}]'::jsonb, NULL, NULL, '南凉皇帝')
