VALUES ('tufa-rutan', '秃发傉檀', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '秃发利鹿孤之弟，402年继位并迁都姑臧；多次与北凉及后秦交战，414年为西秦乞伏炽磐所灭，降后被杀。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秃发傉檀"},{"label":"資治通鑑/卷112","url":"https://zh.wikisource.org/wiki/資治通鑑/卷112"}]'::jsonb, NULL, NULL, '南凉末帝')
