VALUES ('li-xin', '李歆', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '李暠之子，417年继位并迁都酒泉；与北凉争战失利，420年兵败被沮渠蒙逊杀害，西凉亡。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李歆"},{"label":"資治通鑑/卷118","url":"https://zh.wikisource.org/wiki/資治通鑑/卷118"}]'::jsonb, NULL, NULL, '西凉末帝')
