VALUES ('juqu-mengxun', '沮渠蒙逊', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '卢水胡首领，397年参与反吕建北凉，后逐段业掌权；以张掖为中心扩展至河西大部，称河西王，与后秦、南凉等周旋，433年去世。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/沮渠蒙逊"}]'::jsonb, '武宣王', NULL, '北凉武宣王')
