VALUES ('juqu-mujian', '沮渠牧犍', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '沮渠蒙逊之子，433年继位；北魏太武帝于439年攻陷姑臧，沮渠牧犍出降并被迁往平城，北凉河西政权结束。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/沮渠牧犍"},{"label":"《资治通鉴》卷122","url":"https://zh.wikisource.org/wiki/資治通鑑/卷122"}]'::jsonb, NULL, NULL, '北凉末帝')
