VALUES ('helian-bobo', '赫连勃勃', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '匈奴铁弗部首领，407年脱离后秦建夏，后称帝并定都统万城；凭借河套据点袭扰后秦、拓展关中北部，425年去世。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赫连勃勃"}]'::jsonb, '武皇帝', NULL, '胡夏武皇帝')
