VALUES ('helian-chang', '赫连昌', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '赫连勃勃之子，425年继位；北魏攻夏后于427年失统万城，428年被俘，胡夏主力退守关中。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赫连昌"}]'::jsonb, NULL, NULL, '胡夏皇帝')
