VALUES ('helian-ding', '赫连定', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '赫连勃勃之子，赫连昌被俘后于428年继位；431年灭西秦后西行，旋为吐谷浑所俘并送交北魏处死，胡夏亡。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赫连定"},{"label":"資治通鑑/卷121","url":"https://zh.wikisource.org/wiki/資治通鑑/卷121"}]'::jsonb, NULL, NULL, '胡夏末帝')
