VALUES ('xie-an', '谢安', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['政治家'], '东晋陈郡谢氏政治家，长期隐居东山，后出仕任宰相。淝水之战时主持朝政并协调谢玄等将领迎战前秦，战后谢氏声望大增；其从容应对成为后世典故。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/谢安"}]'::jsonb, NULL, NULL, NULL)
