VALUES ('liu-yu-jin', '刘裕', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['军事家','政治家'], '东晋末年权臣，北伐灭南燕、后秦，后代晋建宋。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘裕"}]'::jsonb, NULL, NULL, NULL)
