VALUES ('jia-nanfeng', '贾南风', ARRAY[]::text[], NULL, NULL, 257, 1, NULL, 'year', 300, 1, NULL, 'year', ARRAY['皇后','政治家'], '西晋皇后，出身贾氏，晋惠帝司马衷之妻。惠帝即位后长期干预朝政，先后排斥外戚与政敌；元康年间杀太子司马遹，引发宫廷冲突，后被赵王司马伦废杀。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/贾南风"}]'::jsonb, NULL, NULL, NULL)
