VALUES ('wang-xizhi', '王羲之', ARRAY[]::text[], NULL, NULL, 303, 1, NULL, 'year', 361, 1, NULL, 'year', ARRAY['书法家'], '东晋书法家，字逸少，琅邪临沂人，官至会稽内史。工行、草、楷书，代表作《兰亭集序》被后世奉为行书典范，世称“书圣”；现存作品多为摹本。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/王羲之"}]'::jsonb, NULL, NULL, NULL)
