VALUES ('tao-yuanming', '陶渊明', ARRAY[]::text[], NULL, NULL, 365, 1, NULL, 'year', 427, 1, NULL, 'year', ARRAY['诗人'], '东晋诗人，田园诗派开创者，桃花源记作者；《归去来兮辞》《饮酒》等作品传世；《桃花源记》描绘其理想中的社会图景。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/陶渊明"}]'::jsonb, NULL, NULL, NULL)
