VALUES ('gu-kaizhi', '顾恺之', ARRAY[]::text[], NULL, NULL, 348, 1, NULL, 'year', 409, 1, NULL, 'year', ARRAY['画家'], '东晋画家，字长康，小字虎头，晋陵无锡人。擅长人物画与绘画理论，提出“以形写神”等主张；《女史箴图》《洛神赋图》传为其作，现存本均非确证真迹。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/顾恺之"}]'::jsonb, NULL, NULL, NULL)
