-- dynasties
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('jin-west', '西晋', ARRAY['晋','司马晋'], 'cn', 'east_asia', 266, 2, NULL, 'month', 316, 12, NULL, 'month', 3193, 3803, 'ochre', NULL, NULL, '司马炎于266年承魏禅建立晋朝，定都洛阳，280年灭吴而短暂统一。武帝死后，皇后贾南风与宗室诸王争权引发八王之乱；北方战乱中，汉赵于311年攻陷洛阳、316年迫使长安朝廷出降，西晋覆亡。大量北方人口与士族南迁，为晋室在江南延续统治奠定基础。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('jin-east', '东晋', ARRAY['晋'], 'cn', 'east_asia', 317, 1, NULL, 'year', 420, 7, NULL, 'month', 3804, 5046, 'ochre', NULL, NULL, '西晋覆亡后，司马睿于317年在建康重建晋室，史称东晋；政权以江南为中心，与北方多个政权长期并立，王导、谢安等士族及桓温、刘裕等掌兵重臣深刻影响朝政。383年淝水之战挫败前秦南下，东晋得以延续；此后北伐未能统一，刘裕逐步控制朝廷，420年受禅建立刘宋，东晋结束。北方人口南迁也推动江南开发与政治文化重心南移。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('cheng-han', '{"periods":[{"name":"成","start":{"year":304,"month":1,"confidence":"year"},"end":{"year":337,"month":1,"confidence":"year"}},{"name":"汉","start":{"year":338,"month":1,"confidence":"year"},"end":{"year":347,"month":1,"confidence":"year"}}]}', ARRAY['成汉','成','汉','大成'], 'cn', 'east_asia', 304, 1, NULL, 'year', 347, 1, NULL, 'year', 3648, 4164, 'ochre', NULL, 'wuhu', '巴氐李氏于西晋末在益州建立的政权。李雄以成都为中心稳固统治；李寿一度改国号为汉，347年为东晋桓温所灭。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('han-zhao', '{"periods":[{"name":"汉","start":{"year":304,"month":1,"confidence":"year"},"end":{"year":318,"month":1,"confidence":"year"}},{"name":"赵","start":{"year":319,"month":1,"confidence":"year"},"end":{"year":329,"month":1,"confidence":"year"}}]}', ARRAY['汉赵','汉','前赵','赵'], 'cn', 'east_asia', 304, 1, NULL, 'year', 329, 1, NULL, 'year', 3648, 3948, 'ochre', NULL, 'wuhu', '匈奴刘氏建立，初称汉，后刘曜改国号为赵，史称汉赵或前赵。政权曾攻陷洛阳、长安并终结西晋，后与石勒争夺华北，329年为后赵所灭。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
INSERT INTO dynasties (id, name, alt_names, scope, region, start_year, start_month, start_day, start_confidence, end_year, end_month, end_day, end_confidence, start_abs, end_abs, color_token, parent_id, group_id, note)
VALUES ('zhao-back', '后赵', ARRAY['赵','魏'], 'cn', 'east_asia', 319, 1, NULL, 'year', 351, 1, NULL, 'year', 3828, 4212, 'ochre', NULL, 'wuhu', '羯族石勒建立的政权，定都襄国、后迁邺，曾统治华北大部。石虎死后诸子争位并遭冉闵夺权，石祗于351年败亡。')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, start_year = EXCLUDED.start_year, start_month = EXCLUDED.start_month, start_day = EXCLUDED.start_day, start_confidence = EXCLUDED.start_confidence, end_year = EXCLUDED.end_year, end_month = EXCLUDED.end_month, end_day = EXCLUDED.end_day, end_confidence = EXCLUDED.end_confidence, start_abs = EXCLUDED.start_abs, end_abs = EXCLUDED.end_abs, group_id = EXCLUDED.group_id, note = EXCLUDED.note;
