VALUES ('liang-front', '前凉', ARRAY['凉'], 'cn', 'east_asia', 301, 1, NULL, 'year', 376, 1, NULL, 'year', 3612, 4512, 'ochre', NULL, 'wuhu', '张氏据河西建立的政权，长期奉晋正朔而实际独立，以姑臧为中心。张骏时期势力最盛，376年向前秦出降。')
