VALUES ('yan-front', '前燕', ARRAY['燕'], 'cn', 'east_asia', 337, 1, NULL, 'year', 370, 1, NULL, 'year', 4044, 4440, 'ochre', NULL, 'wuhu', '鲜卑慕容氏据辽东建立的政权，后迁都邺城并扩展至华北。慕容儁灭冉魏后国势达峰，370年为前秦所灭。')
