VALUES ('qin-front', '前秦', ARRAY['秦'], 'cn', 'east_asia', 350, 1, NULL, 'year', 394, 1, NULL, 'year', 4200, 4728, 'ochre', NULL, 'wuhu', '氐族苻氏据关中建立的政权。苻坚、王猛整合北方诸国，淝水之战后诸地相继割据，394年为西秦所灭。')
