VALUES ('yan-back', '后燕', ARRAY['燕'], 'cn', 'east_asia', 384, 1, NULL, 'year', 409, 1, NULL, 'year', 4608, 4908, 'ochre', NULL, 'wuhu', '慕容垂于淝水之战后复兴慕容政权，定都中山并控制河北。慕容垂死后皇位更迭、北魏南进，407年为冯跋所取代。')
