VALUES ('qin-back', '后秦', ARRAY['秦'], 'cn', 'east_asia', 384, 1, NULL, 'year', 417, 1, NULL, 'year', 4608, 5004, 'ochre', NULL, 'wuhu', '羌族姚氏建立、据有关中的政权，姚兴时期扩张并支持佛教译经事业。姚兴死后内乱与刘裕北伐并至，417年后秦亡。')
