VALUES ('qin-xi', '西秦', ARRAY['秦'], 'cn', 'east_asia', 385, 1, NULL, 'year', 431, 1, NULL, 'year', 4620, 5172, 'ochre', NULL, 'wuhu', '鲜卑乞伏氏在陇西、河湟建立的政权，曾降后秦而复国，并灭南凉。431年乞伏暮末降胡夏，西秦结束。')
