VALUES ('liang-back', '后凉', ARRAY['凉'], 'cn', 'east_asia', 386, 1, NULL, 'year', 403, 1, NULL, 'year', 4632, 4836, 'ochre', NULL, 'wuhu', '吕光率前秦军队经营凉州后建立，定都姑臧。吕光晚年继承纷争使河西割据加深，403年吕隆降后秦。')
