VALUES ('liang-south', '南凉', ARRAY['凉'], 'cn', 'east_asia', 397, 1, NULL, 'year', 414, 1, NULL, 'year', 4764, 4968, 'ochre', NULL, 'wuhu', '鲜卑秃发氏在河湟建立的政权，后迁都姑臧；与后凉、北凉、西秦交战，414年为西秦所灭。')
