VALUES ('liang-xi', '西凉', ARRAY['凉'], 'cn', 'east_asia', 400, 1, NULL, 'year', 421, 1, NULL, 'year', 4800, 5052, 'ochre', NULL, 'wuhu', '李暠建立、以敦煌和酒泉为中心的河西政权，注重经营绿洲与屯田。420年李歆败死于北凉，西凉亡。')
