VALUES ('liang-north', '北凉', ARRAY['凉'], 'cn', 'east_asia', 397, 1, NULL, 'year', 439, 1, NULL, 'year', 4764, 5268, 'ochre', NULL, 'wuhu', '卢水胡沮渠氏据河西建立的政权，逐步取代后凉并扩张至河西大部。439年北魏攻陷姑臧，北凉亡。')
