VALUES ('yan-south', '南燕', ARRAY['燕'], 'cn', 'east_asia', 398, 1, NULL, 'year', 410, 1, NULL, 'year', 4776, 4920, 'ochre', NULL, 'wuhu', '慕容德在后燕分裂后据广固建立，统治山东一带。慕容超时期遭东晋刘裕北伐，410年广固陷落，南燕亡。')
